    /// <summary>
    /// Write the record
    /// </summary>
    void write()
    {
        FormDataSource              metInventTransferLineExt_ds;
        METInventTransferLine       metInventTransferLineExt;
        InventTransferLine          metInventTransferLine;

        next write();

        metInventTransferLineExt_ds = this.formRun().dataSource(formDataSourceStr(InventTransferOrders, METInventTransferLine));

        if (metInventTransferLineExt_ds)
        {
            metInventTransferLine      = this.cursor();
            metInventTransferLineExt   = metInventTransferLineExt_ds.cursor();
            
            metInventTransferLine.metPackMETInventTransferLine(metInventTransferLineExt);
            metInventTransferLineExt.SysExtensionSerializerExtensionMap::insertAfterBaseTable(metInventTransferLine);
        }

    }
